const BULAN = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const HARI = ['Ahad','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const tanggalPanjang = (ymd) => {
  const [y, m, d] = ymd.split('-').map(Number);
  const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return HARI[dow] + ', ' + d + ' ' + BULAN[m - 1] + ' ' + y;
};

const config = $('Config').first().json;
const PENGINGAT = { 7: 'Sepekan lagi', 1: 'Besok', 0: 'Hari ini' };

const data = $input.first().json.data;
if (!Array.isArray(data)) {
  throw new Error('Respons /haul tidak berisi data: ' + JSON.stringify($input.first().json).slice(0, 300));
}

return data
  .filter((g) => g.hari_menuju_haul in PENGINGAT)
  .map((g) => {
    const wafat = [g.wafat_hijriah_label ? esc(g.wafat_hijriah_label) + ' H' : null, g.wafat_masehi ? tanggalPanjang(g.wafat_masehi).split(', ')[1] + ' M' : null]
      .filter(Boolean).join(' / ');
    const text = '🤲 <b>Haul ' + esc(g.nama) + '</b>\n'
      + '⏳ <b>' + PENGINGAT[g.hari_menuju_haul] + '</b>: ' + tanggalPanjang(g.haul_berikutnya_masehi) + '\n'
      + (wafat ? '🕯 Wafat: ' + wafat + '\n' : '')
      + '\nMari kita hadiahkan Al-Fatihah untuk beliau, semoga Allah meninggikan derajatnya dan kita mendapat keberkahan ilmunya.\n\n'
      + '<i>Tanggal dihitung dengan kalender Hijriah aritmatis, mungkin berbeda satu hari dari penetapan setempat.</i>\n\n'
      + '📖 <a href="' + esc(g.url) + '">Baca manaqib beliau</a>';
    return { json: { text } };
  });
